column1:
-- 1. Kích hoạt tiện ích mở rộng PostGIS & pg_trgm (Full-text Trigram Search)
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 2. DDL Bảng địa danh Landmarks phục vụ tìm kiếm Autocomplete & Geocoding
CREATE TABLE landmarks (
    landmark_id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL, -- 'Đại học', 'Bệnh viện', 'Ga Metro', 'Bến xe', 'Sân bay', 'Chợ', 'TTTM'
    address TEXT,
    geom GEOMETRY(Point, 4326) NOT NULL,
    popularity_score INT DEFAULT 100
);
CREATE INDEX idx_lm_geom ON landmarks USING GIST (geom);
CREATE INDEX idx_lm_search ON landmarks USING GIN (name gin_trgm_ops);

-- 3. DDL Bảng liên kết trạm dừng theo lộ trình Route Stops
CREATE TABLE route_stops (
    route_id VARCHAR(10) REFERENCES routes(route_id),
    stop_id INT REFERENCES stops(stop_id),
    direction_id SMALLINT NOT NULL, -- 1: Lượt đi, 2: Lượt về
    stop_sequence INT NOT NULL,
    travel_time_from_origin_min NUMERIC(5,2),
    PRIMARY KEY (route_id, direction_id, stop_sequence)
);
CREATE INDEX idx_rs_lookup ON route_stops (route_id, direction_id, stop_sequence);
CREATE INDEX idx_rs_stop_transfer ON route_stops (stop_id);

